function e2State(context is Context, a is Query, b is Query) returns string
{
    var st = "G";
    for (var c in evCollision(context, { "tools" : a, "targets" : b }))
    {
        const t = c["type"] != undefined ? c["type"] : c["clashType"];
        if (t == ClashType.INTERFERE || t == ClashType.TARGET_IN_TOOL || t == ClashType.TOOL_IN_TARGET)
            return "O";
        if (t != ClashType.NONE)
            st = "T";
    }
    return st;
}

function e2R(v is number) returns string
{
    return toString(roundToPrecision(v, 3));
}

