    {
        const base = nomadEBuildBase(context, id + "base", true);
        const lid = nomadEBuildLid(context, id + "lid", { "showReserves" : true, "lidAngle" : 0 * degree, "extR" : 0, "extL" : 0,
                    "tiltR" : 0 * degree, "tiltL" : 0 * degree });
        const parts = mergeMaps(base, lid.parts);
        var fails = [];
        var lumps = 0;
        for (var i = 0; i < size(LE_NAMES); i += 1)
        {
            if (parts[LE_NAMES[i]] == undefined || size(evaluateQuery(context, qBodyType(parts[LE_NAMES[i]], BodyType.SOLID))) != 1)
            {
                lumps += 1;
                if (size(fails) < 6)
                    fails = append(fails, "L" ~ i);
            }
        }
        var stBad = 0;
        var dev = 0;
        var nCmp = 0;
        for (var k = 0; k < size(LE_PAIRS); k += 1)
        {
            const e = LE_PAIRS[k];
            const a = parts[LE_NAMES[e[0]]];
            const b = parts[LE_NAMES[e[1]]];
            var st = e2State(context, a, b);
            if (st != "O" && e[3] >= 0)
            {
                const d = evDistance(context, { "side0" : a, "side1" : b }).distance / millimeter;
                if (st == "G" && d < 1e-6)
                    st = "T";
                dev = max(dev, abs(d - e[3]));
                nCmp += 1;
            }
            if (st != e[2])
            {
                stBad += 1;
                if (size(fails) < 10)
                    fails = append(fails, e[0] ~ "." ~ e[1] ~ st);
            }
        }
        const solids = size(evaluateQuery(context, qAllModifiableSolidBodies()));
