            mdev = max(mdev, norm(cs.origin - vector(c[1], c[2], c[3]) * millimeter) / millimeter);
        }
        var pBad = 0;
        var pdev = 0;
        var posed = {};
        for (var k = 0; k < size(LE_POSES); k += 1)
        {
