            const key = toString(p[0]) ~ "_" ~ toString(p[1]) ~ "_" ~ toString(p[2]) ~ "_" ~ toString(p[3]) ~ "_" ~ toString(p[4]);
            if (posed[key] == undefined)
            {
                const n = size(keys(posed));
                posed[key] = nomadEBuildLid(context, id + ("pose" ~ n), { "showReserves" : true, "lidAngle" : p[0] * degree,
                            "extR" : p[1], "extL" : p[2], "tiltR" : p[3] * degree, "tiltL" : p[4] * degree, "cutPockets" : false }).parts;
            }
            const pp = mergeMaps(base, posed[key]);
            const a = pp[p[5]];
            const b = pp[p[6]];
            const st = e2State(context, a, b);
            var ok = true;
            if (p[7] < -1e-6)
                ok = st == "O";
            else if (st == "O")
                ok = false;
            else
                pdev = max(pdev, abs(evDistance(context, { "side0" : a, "side1" : b }).distance / millimeter - p[7]));
            if (!ok)
            {
                pBad += 1;
                if (size(fails) < 12)
                    fails = append(fails, "P" ~ k ~ st);
            }
        }
        var msg = "E2 n" ~ solids ~ " mc" ~ mcs ~ " L" ~ lumps ~ " S" ~ stBad ~ "/" ~ size(LE_PAIRS) ~ " c" ~ nCmp ~ " dv" ~ e2R(dev) ~
            " m" ~ e2R(mdev) ~ " P" ~ pBad ~ "/" ~ size(LE_POSES) ~ " pd" ~ e2R(pdev) ~ " F:";
        for (var i = 0; i < size(fails); i += 1)
            msg = msg ~ " " ~ fails[i];
        throw regenError(msg);
    }, {});
